<template>
<main class="customer-page"><header class="customer-top"><RouterLink to="/" class="back">‹</RouterLink><div><strong>Randevu Takip</strong><small>Randevunuzu yönetin</small></div><span></span></header><div class="content"><section v-if="!searched" class="card"><p class="eyebrow">RANDEVULARIM</p><h1>Randevunuzu bulun</h1><p class="muted">Randevu oluştururken kullandığınız telefon ve plaka bilgilerini girin.</p><label>Telefon<input v-model="lookup.phone" type="tel" placeholder="05xx xxx xx xx"></label><label>Plaka<input v-model="lookup.plate" @input="lookup.plate=lookup.plate.toUpperCase()" placeholder="34 ABC 123"></label><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="loading" @click="search">{{loading?'Aranıyor…':'Randevularımı Göster'}}</button></section><section v-else><div class="section-head"><div><p class="eyebrow">RANDEVULARIM</p><h1>Randevularınız</h1></div><button class="link" @click="searched=false">Başka bilgi</button></div><div v-if="success" class="success">Randevunuz başarıyla kaydedildi.</div><div v-if="appointments.length" class="appointments"><article v-for="item in appointments" :key="item.id" class="appointment"><div class="date"><strong>{{formatDay(item.date)}}</strong><span>{{item.time}}</span></div><div class="details"><strong>{{item.plate}}</strong><span>{{statusLabel(item.status)}}</span></div><button class="edit" @click="openEdit(item)">Düzenle</button></article></div><div v-else class="empty card">Aktif randevunuz bulunamadı.</div></section></div><div v-if="editing" class="backdrop"><section class="modal"><div class="modal-head"><div><p class="eyebrow">RANDEVU DÜZENLE</p><h2>Yeni zaman seçin</h2></div><button class="close" @click="editing=null">×</button></div><div class="date-scroller"><button v-for="day in days" :key="day.date" class="day" :class="{selected:editDate===day.date}" @click="selectEditDate(day.date)"><small>{{day.weekday}}</small><strong>{{day.day}}</strong><span>{{day.month}}</span></button></div><div v-if="editLoading" class="loading">Saatler yükleniyor…</div><div v-else class="slot-grid"><button v-for="slot in editSlots" :key="slot.time" :disabled="!slot.available" :class="{selected:editTime===slot.time}" @click="editTime=slot.time">{{slot.time}}</button></div><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="!editTime||saving" @click="update">{{saving?'Kaydediliyor…':'Değişikliği Kaydet'}}</button></section></div><nav class="bottom"><RouterLink to="/musteri/hesabim">◉<small>Hesabım</small></RouterLink><RouterLink to="/musteri/ayarlar">⚙<small>Ayarlar</small></RouterLink></nav></main>
</template>
<script setup>
import { onMounted, ref } from "vue"; import { RouterLink } from "vue-router"; import { getCustomerAppointments,getAvailability,updateCustomerAppointment } from "../services/customer";
const lookup=ref({phone:"",plate:""}), appointments=ref([]), searched=ref(false), loading=ref(false), error=ref(""), success=ref(false), editing=ref(null), editDate=ref(""), editTime=ref(""), editSlots=ref([]), editLoading=ref(false), saving=ref(false);
const days=Array.from({length:15},(_,i)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+i);return {date:d.toISOString().slice(0,10),day:d.getDate(),month:d.toLocaleDateString("tr-TR",{month:"short"}).replace(".",""),weekday:i===0?"Bugün":d.toLocaleDateString("tr-TR",{weekday:"short"})}});
function formatDay(x){return new Date(`${x}T12:00:00`).toLocaleDateString("tr-TR",{day:"numeric",month:"short"})} function statusLabel(s){return ({scheduled:"Planlandı",arrived:"İşletmede",in_service:"İşlemde",completed:"Tamamlandı"}[s]||s)}
async function search(){loading.value=true;error.value="";try{const d=await getCustomerAppointments(lookup.value.phone,lookup.value.plate);appointments.value=d.appointments||[];searched.value=true;sessionStorage.setItem("customer_lookup",JSON.stringify(lookup.value))}catch(e){error.value=e.message}finally{loading.value=false}}
async function openEdit(item){editing.value=item;editDate.value=item.date;editTime.value="";await selectEditDate(item.date);}
async function selectEditDate(date){editDate.value=date;editTime.value="";editLoading.value=true;error.value="";try{editSlots.value=(await getAvailability(date)).slots||[]}catch(e){error.value=e.message}finally{editLoading.value=false}}
async function update(){saving.value=true;error.value="";try{await updateCustomerAppointment(editing.value.id,{phone:lookup.value.phone,plate:lookup.value.plate,start_at:`${editDate.value}T${editTime.value}`});editing.value=null;await search()}catch(e){error.value=e.message}finally{saving.value=false}}
onMounted(()=>{try{const saved=JSON.parse(sessionStorage.getItem("customer_lookup")||"null");if(saved){lookup.value=saved;search()}}catch{}})
</script>
<style scoped>
.customer-page{min-height:100vh;background:#f5f7fa;color:#172033;padding-bottom:85px}.customer-top{height:68px;background:#fff;border-bottom:1px solid #e6eaf0;display:grid;grid-template-columns:44px 1fr 44px;align-items:center;padding:0 18px}.customer-top strong,.customer-top small{display:block}.customer-top strong{font-size:15px}.customer-top small{font-size:10px;color:#7b8797}.back{text-decoration:none;color:#334155;font-size:30px}.content{max-width:700px;margin:auto;padding:22px 18px}.card{background:#fff;border:1px solid #e1e7ee;border-radius:18px;padding:24px;box-shadow:0 10px 30px rgba(23,32,51,.04)}.eyebrow{font-size:10px;letter-spacing:.11em;font-weight:850;color:#128c8a;margin:0 0 7px}.card h1,.section-head h1{font-size:25px;margin:0 0 7px}.muted{color:#718096;font-size:12px;line-height:1.5;margin:0 0 20px}.card label{display:grid;gap:6px;font-size:12px;font-weight:750;color:#334155;margin-top:13px}.card input{border:1px solid #d8e0e8;border-radius:10px;padding:12px}.primary{width:100%;border:0;background:#128c8a;color:#fff;border-radius:11px;padding:13px;font-weight:800;cursor:pointer;margin-top:20px}.primary:disabled{opacity:.5}.error{padding:10px 12px;background:#fbeaea;color:#a52e2e;border-radius:9px;font-size:12px}.section-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:15px}.link{border:0;background:none;color:#128c8a;font-size:11px;font-weight:750}.success{padding:11px;background:#e9f7f5;color:#0d746f;border-radius:9px;font-size:12px;margin-bottom:12px}.appointments{display:grid;gap:9px}.appointment{background:#fff;border:1px solid #e1e7ee;border-radius:14px;padding:13px;display:flex;align-items:center;gap:13px}.date{width:66px;text-align:center;border-right:1px solid #e7ebf0}.date strong,.date span{display:block}.date strong{font-size:13px}.date span{font-size:12px;color:#128c8a;font-weight:800;margin-top:3px}.details{flex:1}.details strong,.details span{display:block}.details strong{font-size:13px}.details span{font-size:11px;color:#718096;margin-top:3px}.edit{border:1px solid #d8e0e8;background:#fff;border-radius:8px;padding:8px 10px;color:#334155;font-size:11px;cursor:pointer}.empty{text-align:center;color:#718096;font-size:12px}.backdrop{position:fixed;inset:0;background:rgba(15,23,42,.48);display:grid;place-items:center;padding:18px;z-index:50}.modal{width:min(620px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:18px;padding:22px}.modal-head{display:flex;justify-content:space-between}.modal-head h2{margin:0;font-size:21px}.close{border:0;background:none;font-size:27px;color:#718096}.date-scroller{display:grid;grid-auto-flow:column;grid-auto-columns:72px;gap:8px;overflow-x:auto;padding:12px 0}.day{border:1px solid #dfe6ed;background:#fff;border-radius:12px;padding:9px 5px}.day small,.day strong,.day span{display:block}.day small,.day span{font-size:10px;color:#718096}.day strong{font-size:20px;margin:3px 0}.day.selected{background:#e9f7f5;border-color:#7bc9c4;color:#0d746f}.slot-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.slot-grid button{padding:12px;border:1px solid #dfe6ed;background:#fff;border-radius:9px}.slot-grid button.selected{background:#128c8a;color:#fff;border-color:#128c8a}.slot-grid button:disabled{background:#f1f3f5;color:#b2bac4;text-decoration:line-through}.loading{text-align:center;padding:25px;color:#718096;font-size:12px}.bottom{position:fixed;bottom:0;left:0;right:0;height:68px;background:#fff;border-top:1px solid #e5e9ef;display:flex;justify-content:center;gap:80px}.bottom a{color:#718096;text-decoration:none;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px}.bottom small{font-size:10px}.bottom .router-link-active{color:#128c8a}
</style>
